let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  input += chunk;
});
process.stdin.on('end', () => {
  const numbers = input.split('\n').filter((l) => l.trim() !== '').map(Number);
  if (numbers.length === 0) {
    console.error('No numbers given');
    process.exitCode = 1;
    return;
  }
  console.log(`Total: ${numbers.reduce((a, b) => a + b, 0)}`);
});
